                       (0.5) * sc[16] + sc[17] + (2) * sc[22];
    const amrex::Real redP =
      Corr / k_f * 2.69e+16 * exp(-3.74 * logT - 974.227464997937 * invT);
    const amrex::Real F = redP / (1.0 + redP);
