  kcharge[9] = 0;  // O2
  kcharge[10] = 0; // CH3
  kcharge[11] = 0; // CH4
  kcharge[12] = 0; // HCO
  kcharge[13] = 0; // CH2O
  kcharge[14] = 0; // CH3O
  kcharge[15] = 0; // CH3OH
  kcharge[16] = 0; // CO
  kcharge[17] = 0; // CO2
  kcharge[18] = 0; // C2H2
  kcharge[19] = 0; // C2H3
  kcharge[20] = 0; // C2H4
  kcharge[21] = 0; // C2H5
  kcharge[22] = 0; // C2H6
  kcharge[23] = 0; // HCCO
