  kcharge[26] = 0; // CH2OCH2
  kcharge[27] = 0; // aC3H4
  kcharge[28] = 0; // aC3H5
  kcharge[29] = 0; // C3H6
  kcharge[30] = 0; // nC3H7
  kcharge[31] = 0; // C4H81
